namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Add torn mozzarella pieces.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and garam masala.\n5. Simmer 15 minutes, add cream.\n6. Add chicken pieces and cook 5 more minutes." },
        new Recipe { Id = 4, Title = "Vegetable Samosas", Category = "Indian", Ingredients = "Potatoes, Peas, Cumin, Coriander, Pastry dough, Oil for frying", Steps = "1. Boil and mash potatoes.\n2. Mix with peas, cumin, and coriander.\n3. Roll pastry dough into circles.\n4. Fill with potato mixture and fold into triangles.\n5. Seal edges with water.\n6. Deep fry until golden brown." },
        new Recipe { Id = 5, Title = "Tacos Al Pastor", Category = "Mexican", Ingredients = "Pork shoulder, Pineapple, Achiote paste, Corn tortillas, Onion, Cilantro, Lime", Steps = "1. Marinate pork in achiote and pineapple juice overnight.\n2. Roast pork at 375°F for 2 hours.\n3. Slice thinly.\n4. Warm tortillas on a griddle.\n5. Assemble with pork, diced pineapple, onion, and cilantro.\n6. Squeeze lime over top." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in lime juice and salt.\n4. Fold in diced onion, tomato, jalapeño, and cilantro.\n5. Taste and adjust seasoning.\n6. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs with sugar until fluffy.\n3. Fold in chocolate mixture.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12 minutes.\n7. Invert onto plates and serve immediately." },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers, Mascarpone, Espresso, Eggs, Sugar, Cocoa powder, Marsala wine", Steps = "1. Whisk egg yolks with sugar until pale.\n2. Fold in mascarpone.\n3. Whip egg whites and fold in gently.\n4. Dip ladyfingers in espresso mixed with Marsala.\n5. Layer ladyfingers and cream in a dish.\n6. Refrigerate 4 hours.\n7. Dust with cocoa before serving." },
    };

    private int _nextId = 9;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }
}

