@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= currentRating ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
    @if (averageRating > 0)
    {
        <span class="ms-3 text-muted">Average: @averageRating.ToString("F1") ⭐ (@ratingCount ratings)</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;
    private bool submitted;
    private double averageRating;
    private int ratingCount;

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        currentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            ratingCount = recipe.RatingCount;
        }
    }
}

